import { createReadStream, createWriteStream } from "node:fs";
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { createGzip } from "node:zlib";

let bytes = 0;
const count = new Transform({
  transform(chunk: Buffer, _encoding, done) {
    bytes += chunk.length; // look at the chunk, then pass it on unchanged
    done(null, chunk);
  },
});

await pipeline(createReadStream("runs/big.log"), count, createGzip(), createWriteStream("runs/out/big.log.gz"));
const mb = (n: number) => (n / 1024 / 1024).toFixed(1);
console.log(`read ${mb(bytes)} MB; memory in use ${mb(process.memoryUsage().rss)} MB`);

import { createWriteStream } from "node:fs";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { ReadableStream } from "node:stream/web";

const res = await fetch("https://registry.npmjs.org/zod");
if (!res.ok || !res.body) throw new Error(`download failed: ${res.status}`);
await pipeline(Readable.fromWeb(res.body as ReadableStream), createWriteStream("runs/out/zod.json"));
console.log("saved", res.headers.get("content-type"));

